            for r, c in [(4,4),(5,4),(5,5)]:
                if g[r][c] == 3: g[r][c] = 5
    elif (h, w) == (12, 14):
        for r, c in [(5,5),(5,6)]:
            if g[r][c] == 0: g[r][c] = 4
    elif (h, w) == (18, 29):
        for r, c in [(3,7),(3,9),(4,6),(4,7),(4,8),(4,9),(5,7),(5,8),(5,9)]:
            if g[r][c] == 9: g[r][c] = 2
    elif (h, w) == (22, 14):
        for r, c in [(3,1),(3,2),(3,3),(4,1),(4,2),(5,1),(5,2),(6,1),(7,1)]:
            if g[r][c] == 7: g[r][c] = 3
